function esc(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function renderSection(section) {
  const paragraphs = (section.paragraphs ?? []).map((p) => `<p>${esc(p)}</p>`).join("\n");
  const bullets = section.bullets?.length
    ? `<ul>${section.bullets.map((item) => `<li>${esc(item)}</li>`).join("")}</ul>`
    : "";
  const quote = section.quote ? `<blockquote>${esc(section.quote)}</blockquote>` : "";
  return `<section><div class="dg-insight-container"><h2>${esc(section.heading)}</h2>${paragraphs}${bullets}${quote}</div></section>`;
}

